    explanation: 'Amazon OpenSearch Serverless con colecciones vectoriales es la opción nativa de AWS para almacenamiento y búsqueda de embeddings en pipelines RAG. Soporta algoritmos k-NN optimizados (como HNSW y FAISS) para búsqueda de similitud vectorial eficiente, se integra nativamente con Amazon Bedrock Knowledge Bases, y ofrece escalado serverless que se adapta a la carga de trabajo sin gestión de infraestructura.',
    incorrectExplanations: {
      'd2-q103-a': 'Incorrecto. DynamoDB es una base de datos clave-valor/documento que no soporta nativamente búsqueda de similitud vectorial (k-NN). No tiene índices optimizados para operaciones sobre vectores de alta dimensionalidad.',
      'd2-q103-c': 'Incorrecto. Amazon S3 es almacenamiento de objetos y Athena es un motor de consultas SQL. Ninguno soporta búsqueda de similitud vectorial eficiente. La búsqueda k-NN sobre millones de vectores requiere índices especializados que S3/Athena no proporcionan.',
      'd2-q103-d': 'Incorrecto. Aunque Redis tiene extensiones para búsqueda vectorial (RediSearch), Amazon ElastiCache no es la opción principal para Amazon Bedrock Knowledge Bases y no ofrece la misma integración nativa ni las optimizaciones de búsqueda vectorial de OpenSearch Serverless.',
    },
