    correctAnswers: ['d2-q116-a', 'd2-q116-c'],
    type: 'multiple',
    explanation: 'Dos parámetros diseñados específicamente para combatir repeticiones: (1) Frequency penalty reduce la probabilidad de tokens proporcionalmente a cuántas veces han aparecido (un token que aparece 5 veces recibe 5x la penalización), combatiendo la repetición literal de palabras o frases específicas. (2) Presence penalty aplica una penalización constante a cualquier token que haya aparecido al menos una vez, sin importar cuántas veces, incentivando al modelo a explorar nuevo vocabulario y temas.',
