    explanation: 'Los parámetros de inferencia interactúan en secuencia: (1) La temperatura se aplica primero a los logits, afilando o suavizando la distribución de probabilidad. (2) Luego, top-k filtra la distribución para mantener solo los k tokens más probables. (3) Finalmente, top-p aplica nucleus sampling sobre los tokens restantes, seleccionando el subconjunto cuya probabilidad acumulada alcance p. La restricción más severa domina: si top-k=5 pero top-p seleccionaría 3 tokens, se usan 3. Comprender esta interacción es clave para configurar el comportamiento deseado.',
