    explanation: 'SageMaker Batch Transform es la opción más eficiente en costos para procesar grandes volúmenes de datos sin necesidad de respuesta en tiempo real. Procesa los datos en lotes, aprovisiona la infraestructura solo durante el procesamiento y la libera al finalizar, eliminando costos de endpoints persistentes. Es ideal para escenarios nocturnos con millones de registros.',
