      'd3-q90-b': 'La inferencia asíncrona es adecuada para solicitudes individuales con payloads grandes o tiempos de procesamiento largos, pero no es tan eficiente como Batch Transform para procesar millones de registros de forma masiva. Batch Transform está optimizado específicamente para este caso de uso.',
