      'd3-q105-c': 'El rendimiento aprovisionado requiere un compromiso de compra y es más adecuado para tráfico constante en tiempo real. Para procesamiento por lotes sin requisitos de tiempo real, Batch Inference ofrece mejor relación costo-beneficio.',
      'd3-q105-d': 'Las invocaciones paralelas con la API estándar siguen cobrando el precio bajo demanda completo por cada invocación. No proporcionan ningún descuento y simplemente reducen el tiempo total de procesamiento, no los costos.',
