    type: 'multiple',
    explanation: 'Dos técnicas efectivas: (1) El almacenamiento en caché de prompts (Prompt Caching) de Bedrock permite cachear el prompt del sistema de 3.000 tokens que se repite en cada invocación, eliminando el costo de procesar esos tokens repetidamente y reduciendo la latencia. (2) La destilación de modelo (Model Distillation) permite crear un modelo más pequeño entrenado para replicar las respuestas del modelo grande, ofreciendo costos de inferencia significativamente menores manteniendo una calidad aceptable.',
