      'd3-q106-d': 'Migrar a GPU on-premises implica enormes costos de capital inicial, mantenimiento, electricidad y personal especializado. Para la mayoría de las empresas, los servicios gestionados como Bedrock son más económicos que gestionar infraestructura de GPU propia.',
