    correctAnswers: ['d4-q49-c'],
    type: 'single',
    explanation: 'Difference in Conditional Rejection (DCR) mide específicamente la diferencia en las tasas de falsos positivos entre grupos demográficos. En este escenario, donde el problema es que clientes rurales reciben predicciones positivas (churn) incorrectamente a una tasa mayor, DCR captura exactamente esta disparidad en falsos positivos entre zonas rurales y urbanas.',
