      'd4-q52-c': 'La matriz de correlación muestra relaciones lineales entre características pero no explica cómo el modelo usó esas características para tomar la decisión sobre esta solicitud en particular. Es una herramienta de análisis exploratorio, no de explicabilidad.',
      'd4-q52-d': 'Los coeficientes solo son interpretables en modelos lineales. Para modelos complejos con 50 características, los coeficientes no están disponibles o no son interpretables directamente, y no proporcionan una explicación a nivel de instancia.',
