    explanation: 'El modelo de gradient boosting con explicaciones SHAP post-hoc a través de SageMaker Clarify ofrece el mejor equilibrio: alto rendimiento (R² 0.92) con explicabilidad verificable. SHAP proporciona explicaciones matemáticamente consistentes y aditivas que satisfacen requisitos regulatorios sin sacrificar la capacidad predictiva del modelo.',
