      'd4-q53-c': 'Un ensemble de ambos modelos no necesariamente mejora la interpretabilidad y puede complicarla. La combinación agrega complejidad sin un beneficio claro en explicabilidad sobre usar gradient boosting con SHAP.',
      'd4-q53-d': 'Un sistema basado en reglas manuales es transparente pero sacrifica completamente la capacidad de capturar patrones complejos en los datos. Es una solución extrema cuando existen herramientas que proporcionan explicabilidad sin sacrificar rendimiento.',
