      'd4-q59-c': 'Aunque los word filters de Bedrock Guardrails soportan regex personalizados, usar esta funcionalidad para PII sería reinventar la rueda. Los sensitive information filters ya incluyen detectores predefinidos optimizados para cada tipo de PII, con opciones de BLOCK o ANONYMIZE.',
      'd4-q59-d': 'Bloquear toda conversación que mencione datos personales haría el chatbot inútil para servicio al cliente, donde los usuarios necesariamente comparten información personal. La solución es enmascarar los datos sensibles, no bloquear la conversación.',
