      'd4-q60-b': 'Es imposible crear una lista exhaustiva de afirmaciones prohibidas, y nuevas afirmaciones no verificables surgirían constantemente. Los word filters son para bloquear términos o patrones específicos conocidos, no para evaluar la veracidad del contenido generado.',
      'd4-q60-d': 'Topic denial bloquea temas completos de conversación, no afirmaciones específicas dentro de un tema permitido. Además, bloquear "afirmaciones superlativas" no garantiza que las afirmaciones restantes estén fundamentadas en hechos.',
