    explanation: 'Amazon A2I se integra directamente con Amazon Textract y permite configurar umbrales de confianza que automáticamente envían documentos con baja confianza a revisión humana. A2I gestiona el flujo completo: creación de tareas de revisión, interfaz de usuario para revisores, gestión de workforce, y devolución de resultados al pipeline de procesamiento.',
