      'd4-q64-c': 'SageMaker Ground Truth está diseñado para etiquetar datos de entrenamiento para modelos de ML, no para revisión operacional de predicciones en producción. El escenario requiere revisión de documentos individuales en un flujo operativo, no creación de datasets de entrenamiento.',
      'd4-q64-d': 'Step Functions con SNS requeriría construir toda la infraestructura de revisión desde cero: interfaces de usuario, gestión de tareas, distribución a revisores, y consolidación de resultados. A2I proporciona todo esto como servicio gestionado con integración nativa.',
