    correctAnswers: ['d4-q65-a'],
    type: 'single',
    explanation: 'Amazon A2I permite crear flow definitions con condiciones de activación basadas en scores de confianza de servicios integrados como Rekognition. Se configura un umbral (60-90% en este caso) y un worker task template que define la interfaz de revisión. A2I automáticamente crea tareas de revisión humana cuando Rekognition retorna un score dentro del rango especificado.',
