      'd4-q65-c': 'Ground Truth es para etiquetar datasets de entrenamiento, no para revisión operacional en producción. Además, re-clasificar todas las imágenes ignora el score de confianza de Rekognition y es extremadamente ineficiente.',
      'd4-q65-d': 'Ignorar imágenes con confianza menor al 90% significa que contenido potencialmente inapropiado no sería detectado ni revisado, creando un riesgo significativo de contenido dañino sin moderar en la plataforma.',
