    id: 'd5-q43',
    domain: 5,
    topic: 'cifrado-seguridad',
    difficulty: 'medium',
    question: 'Una empresa farmaceutica almacena datos de ensayos clinicos en Amazon S3 que se utilizan para entrenar modelos en Amazon SageMaker. El equipo de seguridad requiere que todos los datos esten cifrados con claves gestionadas por la organizacion y que se registre cada uso de dichas claves. ¿Cual es la configuracion mas adecuada?',
    options: [
      { id: 'd5-q43-a', text: 'Usar cifrado del lado del servidor con claves administradas por Amazon S3 (SSE-S3) y habilitar CloudTrail para registrar el acceso a los objetos.' },
      { id: 'd5-q43-b', text: 'Usar cifrado del lado del servidor con claves de AWS KMS administradas por el cliente (SSE-KMS con CMK) y habilitar el registro de uso de claves en CloudTrail.' },
      { id: 'd5-q43-c', text: 'Usar cifrado del lado del cliente con claves generadas localmente y almacenarlas en un archivo de configuracion del notebook de SageMaker.' },
      { id: 'd5-q43-d', text: 'Habilitar el cifrado predeterminado de S3 con AES-256 y confiar en los registros de acceso del bucket para la auditoria.' },
    ],
    correctAnswers: ['d5-q43-b'],
    type: 'single',
    explanation: 'SSE-KMS con claves administradas por el cliente (CMK) permite a la organizacion controlar y gestionar sus propias claves de cifrado a traves de AWS KMS. Ademas, cada uso de la clave se registra automaticamente en AWS CloudTrail, proporcionando un rastro de auditoria completo que cumple con los requisitos de seguridad y cumplimiento normativo.',
    incorrectExplanations: {
      'd5-q43-a': 'SSE-S3 utiliza claves gestionadas completamente por AWS, no por la organizacion. No cumple el requisito de que las claves sean administradas por la empresa.',
      'd5-q43-c': 'Almacenar claves de cifrado en archivos de configuracion del notebook es una practica de seguridad deficiente. Ademas, el cifrado del lado del cliente con claves locales no proporciona un registro centralizado de uso de claves.',
      'd5-q43-d': 'AES-256 (SSE-S3) no permite la gestion de claves por parte del cliente, y los registros de acceso del bucket no proporcionan el nivel de detalle de auditoria sobre el uso de claves que ofrece CloudTrail con KMS.',
    },
