    explanation: 'SageMaker Model Monitor detecta desviaciones en la calidad de datos, la calidad del modelo, el sesgo y la explicabilidad en endpoints de produccion. Las alarmas de CloudWatch se integran con Model Monitor para activar acciones automatizadas cuando se detectan desviaciones, como notificar al equipo o iniciar un pipeline de reentrenamiento mediante Step Functions. Esta combinacion proporciona deteccion y respuesta automatizada.',
